  '20260905120629_regions.up.sql': '-- Defines a selling market so cart prices, taxes, and allowed countries agree.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE regions (\n  id              TEXT PRIMARY KEY,\n  name            TEXT NOT NULL,\n  currency_code   TEXT NOT NULL\n                  CHECK (length(currency_code) = 3\n                         AND currency_code = lower(currency_code)),\n  -- Basis points keep tax calculations exact without floating-point rounding.\n  tax_rate        INTEGER NOT NULL CHECK (tax_rate BETWEEN 0 AND 10000),\n  tax_inclusive   INTEGER NOT NULL DEFAULT 0\n                  CHECK (tax_inclusive IN (0, 1)),\n  -- Compact CSV matches the current domain model; application code validates it.\n  countries       TEXT NOT NULL CHECK (length(countries) > 0),\n  automatic_taxes INTEGER NOT NULL DEFAULT 1\n                  CHECK (automatic_taxes IN (0, 1)),\n  -- Extension data remains optional but must be valid JSON when present.\n  metadata        TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at      TEXT NOT NULL DEFAULT\n                  (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at      TEXT NOT NULL DEFAULT\n                  (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion preserves references and historical order meaning.\n  deleted_at      TEXT\n);\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER regions_touch_updated_at AFTER UPDATE ON regions\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE regions SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120630_products.up.sql': '-- Stores the sellable product shell; variants own stock and regional prices.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE products (\n  id          TEXT PRIMARY KEY,\n  -- A product belongs to at most one curated collection, matching Medusa.\n  collection_id TEXT REFERENCES product_collections (id) ON DELETE SET NULL,\n  title       TEXT NOT NULL CHECK (length(title) > 0),\n  -- Optional secondary name shown beneath the merchant-facing title.\n  subtitle    TEXT,\n  -- Stable human-readable lookup key used by storefront URLs.\n  handle      TEXT NOT NULL CHECK (length(handle) > 0),\n  description TEXT,\n  -- Controls whether promotions may reduce this product\'s price.\n  discountable INTEGER NOT NULL DEFAULT 1 CHECK (discountable IN (0, 1)),\n  thumbnail   TEXT,\n  -- Merchant-facing composition shown in product information.\n  material    TEXT,\n  -- ISO 3166-1 alpha-2 country where the product was made.\n  origin_country TEXT CHECK (\n    origin_country IS NULL OR\n    (length(origin_country) = 2 AND origin_country = lower(origin_country))\n  ),\n  -- Simple storefront classification; category hierarchy is separate.\n  product_type TEXT,\n  -- Physical values use the units configured for this store.\n  weight      INTEGER CHECK (weight IS NULL OR weight >= 0),\n  length      INTEGER CHECK (length IS NULL OR length >= 0),\n  width       INTEGER CHECK (width IS NULL OR width >= 0),\n  height      INTEGER CHECK (height IS NULL OR height >= 0),\n  status      TEXT NOT NULL DEFAULT \'draft\'\n              CHECK (status IN (\'draft\', \'published\', \'rejected\', \'proposed\')),\n  -- Validated JSON supports merchant extensions without schema-free core data.\n  metadata    TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at  TEXT NOT NULL DEFAULT\n              (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at  TEXT NOT NULL DEFAULT\n              (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion keeps old order references meaningful.\n  deleted_at  TEXT\n);\n\nCREATE UNIQUE INDEX idx_products_handle ON products (handle)\nWHERE deleted_at IS NULL;\nCREATE INDEX idx_products_status ON products (status)\nWHERE deleted_at IS NULL;\nCREATE INDEX idx_products_collection ON products (collection_id)\nWHERE deleted_at IS NULL AND collection_id IS NOT NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER products_touch_updated_at AFTER UPDATE ON products\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE products SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120631_product_variants.up.sql': '-- Stores purchasable product choices with independent inventory behavior.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_variants (\n  id                 TEXT PRIMARY KEY,\n  product_id         TEXT NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  title              TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 255),\n  -- Material belongs to the sellable choice when variants differ by fabric.\n  material           TEXT CHECK (material IS NULL OR\n                                  length(trim(material)) BETWEEN 1 AND 255),\n  -- External merchant identifiers remain optional but bounded for integrations.\n  sku                TEXT CHECK (sku IS NULL OR\n                                  length(trim(sku)) BETWEEN 1 AND 255),\n  ean                TEXT CHECK (ean IS NULL OR\n                                  length(trim(ean)) BETWEEN 1 AND 255),\n  upc                TEXT CHECK (upc IS NULL OR\n                                  length(trim(upc)) BETWEEN 1 AND 255),\n  barcode            TEXT CHECK (barcode IS NULL OR\n                                  length(trim(barcode)) BETWEEN 1 AND 255),\n  -- Signed stock permits reservations/backorders while policy flags control sale.\n  inventory_quantity INTEGER NOT NULL DEFAULT 0,\n  manage_inventory   INTEGER NOT NULL DEFAULT 1\n                     CHECK (manage_inventory IN (0, 1)),\n  allow_backorder    INTEGER NOT NULL DEFAULT 0\n                     CHECK (allow_backorder IN (0, 1)),\n  -- Physical attributes stay nullable until the merchant supplies fulfillment data.\n  weight             REAL CHECK (weight IS NULL OR weight >= 0),\n  width              REAL CHECK (width IS NULL OR width >= 0),\n  length             REAL CHECK (length IS NULL OR length >= 0),\n  height             REAL CHECK (height IS NULL OR height >= 0),\n  -- Customs identifiers are variant-specific and optional.\n  mid_code          