  '20260905120632_product_options.up.sql': '-- Defines reusable selectable dimensions such as Size or Color.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_options (\n  id         TEXT PRIMARY KEY,\n  -- Merchant-facing axis label; bounded to keep admin forms predictable.\n  title      TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 255),\n  -- Exclusive options disappear with their sole product; globals are reusable.\n  is_exclusive INTEGER NOT NULL DEFAULT 0 CHECK (is_exclusive IN (0, 1)),\n  -- Merchant-only extension data stays outside the public response allowlist.\n  metadata   TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion preserves historical variant and order references.\n  deleted_at TEXT\n);\n\n-- Global titles are unique because merchants select them by meaning.\nCREATE UNIQUE INDEX idx_product_options_global_title\nON product_options (title)\nWHERE deleted_at IS NULL AND is_exclusive = 0;\nCREATE INDEX idx_product_options_title ON product_options (title)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_options_touch_updated_at AFTER UPDATE ON product_options\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_options\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120633_variant_prices.up.sql': '-- Assigns one exact minor-unit price to a variant in each currency.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE variant_prices (\n  variant_id    TEXT NOT NULL REFERENCES product_variants (id)\n                ON DELETE CASCADE,\n  currency_code TEXT NOT NULL\n                CHECK (length(currency_code) = 3\n                       AND currency_code = lower(currency_code)),\n  -- Integer minor units avoid floating-point money errors.\n  amount        INTEGER NOT NULL CHECK (amount >= 0),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- A variant cannot have two competing prices for the same currency.\n  PRIMARY KEY (variant_id, currency_code)\n);\n\n-- Composite keys identify the exact price whose timestamp must advance.\nCREATE TRIGGER variant_prices_touch_updated_at AFTER UPDATE ON variant_prices\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE variant_prices\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE variant_id = NEW.variant_id AND currency_code = NEW.currency_code;\nEND;\n',
  '20260905120634_product_option_values.up.sql': '-- Defines one stable selectable value belonging to a product option.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_option_values (\n  id         TEXT PRIMARY KEY,\n  option_id  TEXT NOT NULL REFERENCES product_options (id) ON DELETE CASCADE,\n  -- Customer-visible choice label; whitespace-only values are never valid.\n  value      TEXT NOT NULL CHECK (length(trim(value)) BETWEEN 1 AND 255),\n  -- Merchant-defined order keeps sizes and swatches stable in every client.\n  rank       INTEGER NOT NULL DEFAULT 0 CHECK (rank >= 0),\n  -- Merchant-only extension data stays outside the public response allowlist.\n  metadata   TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion lets historical variants retain their original selection.\n  deleted_at TEXT,\n  -- Supports the composite child reference that proves option ownership.\n  UNIQUE (id, option_id)\n);\n\nCREATE INDEX idx_option_values_option\nON product_option_values (option_id, rank, id)\nWHERE deleted_at IS NULL;\nCREATE UNIQUE INDEX idx_option_values_option_value\nON product_option_values (option_id, value)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_option_values_touch_updated_at\nAFTER UPDATE ON product_option_values\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_option_values\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120635_customers.up.sql': '-- Stores guest and registered customer profiles separately from credentials.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE customers (\n  id           TEXT PRIMARY KEY,\n  email        TEXT COLLATE NOCASE,\n  company_name TEXT,\n  first_name   TEXT,\n  last_name    TEXT,\n  phone        TEXT,\n  -- Distinguishes checkout-only guests from identities that can sign in.\n  has_account  INTEGER NOT NULL DEFAULT 0 CHECK (has_account IN (0, 1)),\n  metadata     TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion keeps orders auditable without exposing the active profile.\n  deleted_at   TEXT\n);\n\n-- Like Medusa, one guest record and one account record may share an email.\nCREATE UNIQUE INDEX idx_customers_email_account\nON customers (email, has_account)\nWHERE email IS NOT NULL AND deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER customers_touch_updated_at AFTER UPDATE ON customers\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE customers SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120636_carts.up.sql': '-- Stores a mutable shopping session before it becomes an immutable order.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE carts (\n  id           TEXT PRIMARY KEY,\n  region_id    TEXT NOT NULL REFERENCES regions (id),\n  -- Nullable because guest checkout must work before account association.\n  customer_id  TEXT REFERENCES customers (id),\n  email        TEXT COLLATE NOCASE,\n  metadata     TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  -- Set once checkout succeeds so completed carts cannot be treated as active.\n  completed_at TEXT,\n  created_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion retains recovery/audit context.\n  deleted_at   TEXT\n);\n\nCREATE INDEX idx_carts_customer ON carts (customer_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER carts_touch_updated_at AFTER UPDATE ON carts\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE carts SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120637_line_items.up.sql': '-- Stores cart-item snapshots so titles and prices stay stable during checkout.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE line_items (\n  id            TEXT PRIMARY KEY,\n  cart_id       TEXT NOT NULL REFERENCES carts (id) ON DELETE CASCADE,\n  variant_id    TEXT NOT NULL REFERENCES product_variants (id),\n  product_id    TEXT NOT NULL REFERENCES products (id),\n  -- Handle and thumbnail keep historical cart lines navigable and recognisable.\n  product_handle TEXT NOT NULL,\n  thumbnail      TEXT,\n  title         TEXT NOT NULL,\n  variant_title TEXT,\n  -- Integer minor units snapshot the selected price without float errors.\n  unit_amount   INTEGER NOT NULL CHECK (unit_amount >= 0),\n  currency_code TEXT NOT NULL\n                CHECK (length(currency_code) = 3\n                       AND currency_code = lower(currency_code)),\n  quantity      INTEGER NOT NULL CHECK (quantity > 0),\n  metadata      TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion supports removing an item while retaining audit context.\n  deleted_at    TEXT\n);\n\nCREATE INDEX idx_line_items_cart ON line_items (cart_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER line_items_touch_updated_at AFTER UPDATE ON line_items\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE line_items SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120638_orders.up.sql': '-- Stores the immutable commercial snapshot produced by checkout.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE orders (\n  id                 TEXT PRIMARY KEY,\n  -- Short monotonic number is shown to people; opaque ids remain API keys.\n  display_id         INTEGER NOT NULL UNIQUE CHECK (display_id > 0),\n  -- One cart can become one order; this is the checkout idempotency boundary.\n  cart_id            TEXT NOT NULL UNIQUE REFERENCES carts (id),\n  region_id          TEXT NOT NULL REFERENCES regions (id),\n  customer_id        TEXT REFERENCES customers (id),\n  email              TEXT NOT NULL COLLATE NOCASE,\n  currency_code      TEXT NOT NULL\n                     CHECK (length(currency_code) = 3\n                            AND currency_code = lower(currency_code)),\n  -- Every monetary value is an integer in the currency\'s minor unit.\n  subtotal           INTEGER NOT NULL CHECK (subtotal >= 0),\n  shipping_total     INTEGER NOT NULL DEFAULT 0 CHECK (shipping_total >= 0),\n  discount_total     INTEGER NOT NULL DEFAULT 0 CHECK (discount_total >= 0),\n  tax                INTEGER NOT NULL CHECK (tax >= 0),\n  total              INTEGER NOT NULL CHECK (total >= 0),\n  status             TEXT NOT NULL DEFAULT \'pending\'\n                     CHECK (status IN (\'pending\', \'completed\', \'cancelled\')),\n  payment_status     TEXT NOT NULL DEFAULT \'awaiting\'\n                     CHECK (payment_status IN (\'awaiting\', \'captured\', \'refunded\')),\n  -- Shipping/promotion labels are copied so later catalog edits do not rewrite history.\n  shipping_option_id TEXT,\n  shipping_name      TEXT,\n  promotion_code     TEXT,\n  metadata           TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  -- Business event time is explicit; created_at remains the database insert time.\n  placed_at          TEXT NOT NULL,\n  created_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  deleted_at         TEXT,\n  -- Database checks make a corrupted or contradictory order total impossible.\n  CHECK (discount_total <= subtotal + shipping_total),\n  CHECK (total = subtotal + shipping_total - discount_total + tax)\n);\n\nCREATE INDEX idx_orders_customer ON orders (customer_id)\nWHERE deleted_at IS NULL;\nCREATE INDEX idx_orders_email ON orders (email)\nWHERE deleted_at IS NULL;\nCREATE INDEX idx_orders_placed_at ON orders (placed_at);\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER orders_touch_updated_at AFTER UPDATE ON orders\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE orders SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120639_order_items.up.sql': '-- Stores order-time item snapshots independent of mutable catalog records.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE order_items (\n  id            TEXT PRIMARY KEY,\n  order_id      TEXT NOT NULL REFERENCES orders (id) ON DELETE CASCADE,\n  -- IDs intentionally have no FK so deleting catalog data cannot erase history.\n  variant_id    TEXT NOT NULL,\n  product_id    TEXT NOT NULL,\n  product_handle TEXT NOT NULL,\n  thumbnail      TEXT,\n  title         TEXT NOT NULL,\n  variant_title TEXT,\n  -- Integer minor units preserve exact historical pricing.\n  unit_amount   INTEGER NOT NULL CHECK (unit_amount >= 0),\n  currency_code TEXT NOT NULL\n                CHECK (length(currency_code) = 3\n                       AND currency_code = lower(currency_code)),\n  quantity      INTEGER NOT NULL CHECK (quantity > 0),\n  metadata      TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\'))\n);\n\nCREATE INDEX idx_order_items_order ON order_items (order_id);\n\n-- Maintains audit timestamps if administrative correction is ever required.\nCREATE TRIGGER order_items_touch_updated_at AFTER UPDATE ON order_items\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE order_items SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120640_order_addresses.up.sql': '-- Stores shipping and billing snapshots as they were when the order was placed.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE order_addresses (\n  order_id     TEXT NOT NULL REFERENCES orders (id) ON DELETE CASCADE,\n  -- Composite key permits at most one address of each role per order.\n  kind         TEXT NOT NULL CHECK (kind IN (\'shipping\', \'billing\')),\n  first_name   TEXT NOT NULL,\n  last_name    TEXT NOT NULL,\n  -- Optional organization is distinct from the secondary street line.\n  company      TEXT,\n  line1        TEXT NOT NULL,\n  line2        TEXT,\n  city         TEXT NOT NULL,\n  province     TEXT,\n  postal_code  TEXT NOT NULL,\n  -- Lowercase ISO 3166-1 alpha-2 code keeps region comparisons deterministic.\n  country_code TEXT NOT NULL\n               CHECK (length(country_code) = 2\n                      AND country_code = lower(country_code)),\n  phone        TEXT,\n  created_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  PRIMARY KEY (order_id, kind)\n);\n\n-- Composite keys identify the exact address whose timestamp must advance.\nCREATE TRIGGER order_addresses_touch_updated_at AFTER UPDATE ON order_addresses\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE order_addresses\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE order_id = NEW.order_id AND kind = NEW.kind;\nEND;\n',
  '20260905120641_shipping_options.up.sql': '-- Defines a region-specific delivery choice and its exact checkout charge.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE shipping_options (\n  id            TEXT PRIMARY KEY,\n  region_id     TEXT NOT NULL REFERENCES regions (id) ON DELETE CASCADE,\n  name          TEXT NOT NULL CHECK (length(name) > 0),\n  -- Integer minor units avoid floating-point money errors.\n  amount        INTEGER NOT NULL CHECK (amount >= 0),\n  currency_code TEXT NOT NULL\n                CHECK (length(currency_code) = 3\n                       AND currency_code = lower(currency_code)),\n  metadata      TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion hides the option without invalidating existing orders.\n  deleted_at    TEXT\n);\n\nCREATE INDEX idx_shipping_options_region ON shipping_options (region_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER shipping_options_touch_updated_at AFTER UPDATE ON shipping_options\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE shipping_options\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120642_cart_shipping_methods.up.sql': '-- Snapshots the single shipping method currently selected for a cart.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE cart_shipping_methods (\n  cart_id    TEXT PRIMARY KEY REFERENCES carts (id) ON DELETE CASCADE,\n  option_id  TEXT NOT NULL REFERENCES shipping_options (id),\n  -- Name and amount are copied so later shipping-option edits do not change totals.\n  name       TEXT NOT NULL,\n  amount     INTEGER NOT NULL CHECK (amount >= 0),\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\'))\n);\n\n-- Upserts change the quote in place, so the database advances updated_at.\nCREATE TRIGGER cart_shipping_touch_updated_at AFTER UPDATE ON cart_shipping_methods\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE cart_shipping_methods\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE cart_id = NEW.cart_id;\nEND;\n',
  '20260905120643_promotions.up.sql': '-- Defines redeemable discount policy and its bounded usage window.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE promotions (\n  id            TEXT PRIMARY KEY,\n  code          TEXT NOT NULL COLLATE NOCASE,\n  type          TEXT NOT NULL CHECK (type IN (\'percentage\', \'fixed\')),\n  -- Percentage values are basis points; fixed values are currency minor units.\n  value         INTEGER NOT NULL CHECK (value >= 0),\n  currency_code TEXT\n                CHECK (currency_code IS NULL OR\n                       (length(currency_code) = 3\n                        AND currency_code = lower(currency_code))),\n  starts_at     TEXT,\n  ends_at       TEXT,\n  usage_limit   INTEGER CHECK (usage_limit IS NULL OR usage_limit > 0),\n  -- Persisted count lets checkout enforce a global redemption limit atomically.\n  usage_count   INTEGER NOT NULL DEFAULT 0 CHECK (usage_count >= 0),\n  metadata      TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  deleted_at    TEXT,\n  -- Cross-column checks prevent internally contradictory promotion definitions.\n  CHECK (type != \'percentage\' OR value <= 10000),\n  CHECK (type != \'fixed\' OR currency_code IS NOT NULL),\n  CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),\n  CHECK (usage_limit IS NULL OR usage_count <= usage_limit)\n);\n\nCREATE UNIQUE INDEX idx_promotions_code ON promotions (code)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER promotions_touch_updated_at AFTER UPDATE ON promotions\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE promotions SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120644_cart_promotions.up.sql': '-- Snapshots the single promotion currently applied to a cart.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE cart_promotions (\n  cart_id       TEXT PRIMARY KEY REFERENCES carts (id) ON DELETE CASCADE,\n  promotion_id  TEXT NOT NULL REFERENCES promotions (id),\n  -- Customer-facing policy fields are frozen with the calculated amount.\n  code          TEXT NOT NULL,\n  type          TEXT NOT NULL CHECK (type IN (\'percentage\', \'fixed\')),\n  -- Percentage values are basis points; fixed values are currency minor units.\n  value         INTEGER NOT NULL CHECK (value >= 0),\n  currency_code TEXT\n                CHECK (currency_code IS NULL OR\n                       (length(currency_code) = 3\n                        AND currency_code = lower(currency_code))),\n  amount        INTEGER NOT NULL CHECK (amount >= 0),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- A percentage is currency-free; a fixed value must name its currency.\n  CHECK ((type = \'percentage\' AND currency_code IS NULL) OR\n         (type = \'fixed\' AND currency_code IS NOT NULL)),\n  CHECK (type != \'percentage\' OR value <= 10000)\n);\n\n-- Upserts change the applied discount in place, so updated_at must advance.\nCREATE TRIGGER cart_promotions_touch_updated_at AFTER UPDATE ON cart_promotions\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE cart_promotions\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE cart_id = NEW.cart_id;\nEND;\n',
  '20260905120645_variant_option_values.up.sql': '-- Links a variant to one stable value for each of its product options.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE variant_option_values (\n  variant_id     TEXT NOT NULL\n                 REFERENCES product_variants (id) ON DELETE CASCADE,\n  option_id      TEXT NOT NULL,\n  option_value_id TEXT NOT NULL,\n  created_at     TEXT NOT NULL DEFAULT\n                 (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at     TEXT NOT NULL DEFAULT\n                 (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- One row per pair prevents a variant selecting two values for one option.\n  PRIMARY KEY (variant_id, option_id),\n  -- The composite key prevents linking a value owned by another option.\n  FOREIGN KEY (option_value_id, option_id)\n    REFERENCES product_option_values (id, option_id) ON DELETE CASCADE\n);\n\nCREATE INDEX idx_variant_values_option_value\nON variant_option_values (option_value_id, variant_id);\n\n-- Composite keys identify the exact selection whose timestamp must advance.\nCREATE TRIGGER variant_values_touch_updated_at\nAFTER UPDATE ON variant_option_values\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE variant_option_values\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE variant_id = NEW.variant_id AND option_id = NEW.option_id;\nEND;\n',
  '20260905120646_payment_collections.up.sql': '-- Tracks money collection for an order without storing provider card secrets.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE payment_collections (\n  id            TEXT PRIMARY KEY,\n  -- One order has one collection; retries must reuse it, never double charge.\n  order_id      TEXT NOT NULL UNIQUE REFERENCES orders (id) ON DELETE CASCADE,\n  -- Identifies the external adapter; provider-specific state belongs in metadata.\n  provider      TEXT NOT NULL CHECK (length(provider) > 0),\n  -- Integer minor units avoid floating-point money errors.\n  amount        INTEGER NOT NULL CHECK (amount >= 0),\n  currency_code TEXT NOT NULL\n                CHECK (length(currency_code) = 3\n                       AND currency_code = lower(currency_code)),\n  status        TEXT NOT NULL\n                CHECK (status IN (\'pending\', \'authorized\', \'captured\',\n                                  \'cancelled\', \'failed\')),\n  metadata      TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at    TEXT NOT NULL DEFAULT\n                (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Set only when funds actually move; status alone is not an event timestamp.\n  captured_at   TEXT,\n  deleted_at    TEXT\n);\n\nCREATE INDEX idx_payment_collections_order ON payment_collections (order_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER payments_touch_updated_at AFTER UPDATE ON payment_collections\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE payment_collections\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120647_auth_identity.up.sql': '-- Medusa separates the actor from any provider used to authenticate it.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE auth_identity (\n  id           TEXT PRIMARY KEY,\n  -- Trusted application links (currently customer_id); clients cannot write it.\n  app_metadata TEXT CHECK (app_metadata IS NULL OR json_valid(app_metadata)),\n  created_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  deleted_at   TEXT\n);\n\nCREATE INDEX idx_auth_identity_deleted_at ON auth_identity (deleted_at)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER auth_identity_touch_updated_at AFTER UPDATE ON auth_identity\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE auth_identity SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120648_provider_identity.up.sql': '-- Email/password is one provider. Its provider_metadata holds a self-describing\n-- Argon2id PHC string; the password itself is never stored.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE provider_identity (\n  id                TEXT PRIMARY KEY,\n  -- Provider-scoped login identifier; emailpass stores normalized email here.\n  entity_id         TEXT NOT NULL CHECK (length(entity_id) > 0),\n  provider          TEXT NOT NULL CHECK (length(provider) > 0),\n  auth_identity_id  TEXT NOT NULL REFERENCES auth_identity (id)\n                    ON UPDATE CASCADE ON DELETE CASCADE,\n  -- Untrusted provider profile data is kept apart from trusted app metadata.\n  user_metadata     TEXT\n                    CHECK (user_metadata IS NULL OR json_valid(user_metadata)),\n  provider_metadata TEXT\n                    CHECK (provider_metadata IS NULL OR json_valid(provider_metadata)),\n  created_at        TEXT NOT NULL DEFAULT\n                    (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at        TEXT NOT NULL DEFAULT\n                    (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  deleted_at        TEXT\n);\n\nCREATE INDEX idx_provider_identity_auth ON provider_identity (auth_identity_id)\nWHERE deleted_at IS NULL;\nCREATE UNIQUE INDEX idx_provider_identity_entity_provider\nON provider_identity (entity_id COLLATE NOCASE, provider)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER provider_identity_touch_updated_at AFTER UPDATE ON provider_identity\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE provider_identity\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120649_auth_tokens.up.sql': '-- This service uses revocable opaque sessions instead of Medusa\'s JWT stack.\n-- Only the SHA-256 fingerprint is stored, so a database read cannot replay it.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE auth_tokens (\n  token_hash       TEXT PRIMARY KEY CHECK (length(token_hash) = 64),\n  auth_identity_id TEXT NOT NULL REFERENCES auth_identity (id)\n                   ON UPDATE CASCADE ON DELETE CASCADE,\n  created_at       TEXT NOT NULL DEFAULT\n                   (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Explicit expiry provides bounded sessions without relying on cleanup timing.\n  expires_at       TEXT NOT NULL,\n  CHECK (expires_at > created_at)\n);\n\nCREATE INDEX idx_auth_tokens_identity ON auth_tokens (auth_identity_id);\nCREATE INDEX idx_auth_tokens_expiry ON auth_tokens (expires_at);\n',
  '20260905120650_product_images.up.sql': '-- Stores the ordered image gallery for a product independently from variants.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_images (\n  id         TEXT PRIMARY KEY,\n  product_id TEXT NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  -- Remote merchant asset rendered by the storefront.\n  url        TEXT NOT NULL CHECK (length(url) > 0),\n  -- Stable ordering avoids relying on insertion order in gallery responses.\n  rank       INTEGER NOT NULL CHECK (rank >= 0),\n  -- Optional extension data must remain valid JSON.\n  metadata   TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion removes an asset without erasing its audit history.\n  deleted_at TEXT,\n  UNIQUE (product_id, rank)\n);\n\nCREATE INDEX idx_product_images_product ON product_images (product_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_images_touch_updated_at AFTER UPDATE ON product_images\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_images\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120651_product_categories.up.sql': '-- Defines a nested storefront category tree with stable path handles.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_categories (\n  id                 TEXT PRIMARY KEY,\n  -- Customer-facing category name.\n  name               TEXT NOT NULL CHECK (length(trim(name)) > 0),\n  description        TEXT,\n  -- Full stable route path, such as clothing/shirts for a nested category.\n  handle             TEXT NOT NULL CHECK (length(trim(handle)) > 0),\n  -- Self-reference establishes the navigation hierarchy without JSON nesting.\n  parent_category_id TEXT REFERENCES product_categories (id)\n                     ON DELETE SET NULL,\n  -- Inactive categories remain editable but never appear in the store.\n  is_active          INTEGER NOT NULL DEFAULT 1\n                     CHECK (is_active IN (0, 1)),\n  -- Sibling display order; identifiers remain independent of presentation.\n  rank               INTEGER NOT NULL DEFAULT 0 CHECK (rank >= 0),\n  -- Validated JSON supports merchant extensions outside the public contract.\n  metadata           TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  deleted_at         TEXT,\n  CHECK (parent_category_id IS NULL OR parent_category_id != id)\n);\n\nCREATE UNIQUE INDEX idx_product_categories_handle\nON product_categories (handle) WHERE deleted_at IS NULL;\nCREATE INDEX idx_product_categories_parent\nON product_categories (parent_category_id, rank)\nWHERE deleted_at IS NULL AND is_active = 1;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_categories_touch_updated_at\nAFTER UPDATE ON product_categories\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_categories\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120652_product_category_products.up.sql': '-- Links products to every public category in which they should be discovered.\nCREATE TABLE product_category_products (\n  product_id  TEXT NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  category_id TEXT NOT NULL REFERENCES product_categories (id)\n              ON DELETE CASCADE,\n  -- Category-specific ordering without changing product or category identity.\n  rank        INTEGER NOT NULL DEFAULT 0 CHECK (rank >= 0),\n  PRIMARY KEY (product_id, category_id)\n);\n\nCREATE INDEX idx_product_category_products_category\nON product_category_products (category_id, rank, product_id);\n',
  '20260905120653_product_tags.up.sql': '-- Defines public discovery labels that can be shared by many products.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_tags (\n  id         TEXT PRIMARY KEY,\n  -- Customer-facing label; uniqueness is case-insensitive while active.\n  value      TEXT NOT NULL CHECK (length(trim(value)) > 0),\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  deleted_at TEXT\n);\n\nCREATE UNIQUE INDEX idx_product_tags_value\nON product_tags (lower(value)) WHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_tags_touch_updated_at AFTER UPDATE ON product_tags\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_tags\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260905120654_product_tag_products.up.sql': '-- Links a product to each public tag used for filtering and discovery.\nCREATE TABLE product_tag_products (\n  product_id TEXT NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  tag_id     TEXT NOT NULL REFERENCES product_tags (id) ON DELETE CASCADE,\n  PRIMARY KEY (product_id, tag_id)\n);\n\nCREATE INDEX idx_product_tag_products_tag\nON product_tag_products (tag_id, product_id);\n',
  '20260905120655_customer_addresses.up.sql': '-- Stores reusable customer destinations separately from immutable order snapshots.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE customer_addresses (\n  id                  TEXT PRIMARY KEY,\n  customer_id         TEXT NOT NULL REFERENCES customers (id)\n                      ON DELETE CASCADE,\n  first_name          TEXT NOT NULL CHECK (length(trim(first_name)) > 0),\n  last_name           TEXT NOT NULL CHECK (length(trim(last_name)) > 0),\n  company             TEXT,\n  phone               TEXT,\n  address_1           TEXT NOT NULL CHECK (length(trim(address_1)) > 0),\n  address_2           TEXT,\n  city                TEXT NOT NULL CHECK (length(trim(city)) > 0),\n  province            TEXT,\n  postal_code         TEXT NOT NULL CHECK (length(trim(postal_code)) > 0),\n  -- Lowercase ISO code makes region and country comparisons deterministic.\n  country_code        TEXT NOT NULL\n                      CHECK (length(country_code) = 2\n                             AND country_code = lower(country_code)),\n  -- Each role has at most one active default per customer.\n  is_default_shipping INTEGER NOT NULL DEFAULT 0\n                      CHECK (is_default_shipping IN (0, 1)),\n  is_default_billing  INTEGER NOT NULL DEFAULT 0\n                      CHECK (is_default_billing IN (0, 1)),\n  metadata            TEXT CHECK (metadata IS NULL OR json_valid(metadata)),\n  created_at          TEXT NOT NULL DEFAULT\n                      (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at          TEXT NOT NULL DEFAULT\n                      (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion preserves audit history without returning stale destinations.\n  deleted_at          TEXT\n);\n\nCREATE INDEX idx_customer_addresses_customer\nON customer_addresses (customer_id, created_at, id)\nWHERE deleted_at IS NULL;\nCREATE UNIQUE INDEX idx_customer_addresses_default_shipping\nON customer_addresses (customer_id)\nWHERE deleted_at IS NULL AND is_default_shipping = 1;\nCREATE UNIQUE INDEX idx_customer_addresses_default_billing\nON customer_addresses (customer_id)\nWHERE deleted_at IS NULL AND is_default_billing = 1;\n\n-- Selecting a new default atomically clears the previous active destination.\nCREATE TRIGGER customer_addresses_default_shipping_insert\nBEFORE INSERT ON customer_addresses\nWHEN NEW.is_default_shipping = 1 BEGIN\n  UPDATE customer_addresses SET is_default_shipping = 0\n  WHERE customer_id = NEW.customer_id AND deleted_at IS NULL;\nEND;\nCREATE TRIGGER customer_addresses_default_billing_insert\nBEFORE INSERT ON customer_addresses\nWHEN NEW.is_default_billing = 1 BEGIN\n  UPDATE customer_addresses SET is_default_billing = 0\n  WHERE customer_id = NEW.customer_id AND deleted_at IS NULL;\nEND;\nCREATE TRIGGER customer_addresses_default_shipping_update\nBEFORE UPDATE OF is_default_shipping ON customer_addresses\nWHEN NEW.is_default_shipping = 1 BEGIN\n  UPDATE customer_addresses SET is_default_shipping = 0\n  WHERE customer_id = NEW.customer_id AND id != NEW.id\n    AND deleted_at IS NULL;\nEND;\nCREATE TRIGGER customer_addresses_default_billing_update\nBEFORE UPDATE OF is_default_billing ON customer_addresses\nWHEN NEW.is_default_billing = 1 BEGIN\n  UPDATE customer_addresses SET is_default_billing = 0\n  WHERE customer_id = NEW.customer_id AND id != NEW.id\n    AND deleted_at IS NULL;\nEND;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER customer_addresses_touch_updated_at\nAFTER UPDATE ON customer_addresses\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE customer_addresses\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260906120000_shipping_option_price_rules.up.sql': '-- Defines the cart-value condition that makes one delivery option available.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE shipping_option_price_rules (\n  -- Stable identifier lets operational tooling address one rule safely.\n  id                 TEXT PRIMARY KEY,\n  -- Removing an option removes conditions that can no longer be evaluated.\n  shipping_option_id TEXT NOT NULL\n                     REFERENCES shipping_options (id) ON DELETE CASCADE,\n  -- The measured cart fact is explicit so new rule kinds require a decision.\n  attribute          TEXT NOT NULL CHECK (attribute IN (\'item_total\')),\n  -- The comparison is stored rather than inferred from a marketing label.\n  operator           TEXT NOT NULL\n                     CHECK (operator IN (\'gt\', \'gte\', \'lt\', \'lte\', \'eq\')),\n  -- Integer minor units match cart totals without floating-point rounding.\n  value              INTEGER NOT NULL CHECK (value >= 0),\n  -- Creation time supports audit and deterministic operational inspection.\n  created_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- The trigger below advances this when an operator edits the rule.\n  updated_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion withdraws a rule without losing its history immediately.\n  deleted_at         TEXT,\n  UNIQUE (shipping_option_id, attribute, operator, value)\n);\n\nCREATE INDEX idx_shipping_option_price_rules_option\nON shipping_option_price_rules (shipping_option_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER shipping_option_price_rules_touch_updated_at\nAFTER UPDATE ON shipping_option_price_rules\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE shipping_option_price_rules\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260906120001_order_transfers.up.sql': '-- Stores a customer\'s request to take ownership of an existing order.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE order_transfers (\n  -- Public opaque identifier used to retry the same transfer safely.\n  id                 TEXT PRIMARY KEY,\n  -- The order whose ownership may move after the current contact approves.\n  order_id           TEXT NOT NULL REFERENCES orders (id) ON DELETE CASCADE,\n  -- The registered account that will own the order after acceptance.\n  customer_id        TEXT NOT NULL REFERENCES customers (id) ON DELETE CASCADE,\n  -- Only the SHA-256 fingerprint remains after delivery, so a database read\n  -- cannot replay a transfer link that has already left the outbox.\n  token_fingerprint  TEXT NOT NULL UNIQUE\n                     CHECK (length(token_fingerprint) = 64\n                            AND token_fingerprint NOT GLOB \'*[^0-9a-f]*\'),\n  -- Raw capability retained only while SMTP delivery is pending or leased.\n  delivery_token     TEXT,\n  -- A request is final after acceptance, refusal, or expiry.\n  status             TEXT NOT NULL DEFAULT \'requested\'\n                     CHECK (status IN (\'requested\', \'accepted\', \'declined\', \'expired\')),\n  -- Tracks whether the capability is still queued, leased, or delivered.\n  delivery_status    TEXT NOT NULL DEFAULT \'queued\'\n                     CHECK (delivery_status IN (\'queued\', \'sending\', \'sent\', \'cancelled\')),\n  -- Counts lease acquisitions for delivery observability and retry diagnosis.\n  delivery_attempts  INTEGER NOT NULL DEFAULT 0 CHECK (delivery_attempts >= 0),\n  -- A crashed sender can be reclaimed after this short delivery lease expires.\n  delivery_lease_until TEXT,\n  -- Stores only a sanitised category, never an SMTP credential or token.\n  last_delivery_error  TEXT,\n  -- The owner decision capability stops working at this UTC instant.\n  expires_at         TEXT NOT NULL,\n  -- Records when the target customer asked for this ownership transfer.\n  requested_at       TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Records the final decision or expiry time; absent while requested.\n  decided_at         TEXT,\n  -- Records SMTP acceptance, which is delivery rather than mailbox receipt.\n  sent_at            TEXT,\n  -- Audit timestamp generated by SQLite when the row is first inserted.\n  created_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Audit timestamp maintained by the trigger after every mutation.\n  updated_at         TEXT NOT NULL DEFAULT\n                     (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  CHECK (\n    (status = \'requested\' AND decided_at IS NULL) OR\n    (status <> \'requested\' AND decided_at IS NOT NULL)\n  ),\n  CHECK (\n    (delivery_status = \'queued\' AND status = \'requested\'\n      AND delivery_token IS NOT NULL\n      AND delivery_lease_until IS NULL AND sent_at IS NULL) OR\n    (delivery_status = \'sending\' AND status = \'requested\'\n      AND delivery_token IS NOT NULL\n      AND delivery_lease_until IS NOT NULL AND sent_at IS NULL) OR\n    (delivery_status = \'sent\' AND delivery_token IS NULL\n      AND delivery_lease_until IS NULL AND sent_at IS NOT NULL) OR\n    (delivery_status = \'cancelled\' AND delivery_token IS NULL\n      AND delivery_lease_until IS NULL AND sent_at IS NULL)\n  )\n);\n\n-- At most one undecided request may compete for an order at a time.\nCREATE UNIQUE INDEX idx_order_transfers_active_order\nON order_transfers (order_id)\nWHERE status = \'requested\';\n\nCREATE INDEX idx_order_transfers_customer\nON order_transfers (customer_id, requested_at DESC);\n\n-- Makes pending or abandoned SMTP work cheap to reclaim.\nCREATE INDEX idx_order_transfers_delivery\nON order_transfers (delivery_status, delivery_lease_until)\nWHERE delivery_status IN (\'queued\', \'sending\');\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER order_transfers_touch_updated_at AFTER UPDATE ON order_transfers\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE order_transfers\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260906120002_cart_addresses.up.sql': '-- Retains checkout destinations on the mutable cart across reloads and retries.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE cart_addresses (\n  cart_id      TEXT NOT NULL REFERENCES carts (id) ON DELETE CASCADE,\n  -- One shipping row and at most one separate billing row belong to a cart.\n  kind         TEXT NOT NULL CHECK (kind IN (\'shipping\', \'billing\')),\n  first_name   TEXT NOT NULL,\n  last_name    TEXT NOT NULL,\n  -- Organization stays distinct from apartment, suite, or secondary street.\n  company      TEXT,\n  line1        TEXT NOT NULL,\n  line2        TEXT,\n  city         TEXT NOT NULL,\n  province     TEXT,\n  postal_code  TEXT NOT NULL,\n  -- Lowercase ISO 3166-1 alpha-2 code validated against the cart region.\n  country_code TEXT NOT NULL CHECK (\n    length(country_code) = 2 AND country_code = lower(country_code)\n  ),\n  phone        TEXT,\n  created_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at   TEXT NOT NULL DEFAULT\n               (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  PRIMARY KEY (cart_id, kind)\n);\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER cart_addresses_touch_updated_at\nAFTER UPDATE ON cart_addresses\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE cart_addresses\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE cart_id = NEW.cart_id AND kind = NEW.kind;\nEND;\n',
  '20260906150000_admin_users.up.sql': '-- Stores people allowed to operate the merchant-only admin API.\n-- Authentication credentials remain in provider_identity, not this profile.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE admin_users (\n  -- Opaque public identifier; authorization resolves it through auth_identity.\n  id         TEXT PRIMARY KEY,\n  -- Normalized sign-in address and operational contact identifier.\n  email      TEXT NOT NULL COLLATE NOCASE\n             CHECK (length(email) BETWEEN 3 AND 254),\n  -- Optional display names must never be used as authorization facts.\n  first_name TEXT CHECK (first_name IS NULL OR length(first_name) BETWEEN 1 AND 100),\n  -- Optional family name is display data, never an authorization fact.\n  last_name  TEXT CHECK (last_name IS NULL OR length(last_name) BETWEEN 1 AND 100),\n  -- Disabled users retain audit relationships but cannot authenticate.\n  status     TEXT NOT NULL DEFAULT \'active\'\n             CHECK (status IN (\'active\', \'disabled\')),\n  -- Audit creation instant generated by SQLite in UTC.\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Audit mutation instant maintained by the trigger below.\n  updated_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion preserves the actor named by future audit records.\n  deleted_at TEXT\n);\n\nCREATE UNIQUE INDEX idx_admin_users_email_active\nON admin_users (email COLLATE NOCASE)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER admin_users_touch_updated_at AFTER UPDATE ON admin_users\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE admin_users\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260906150001_cart_payment_sessions.up.sql': '-- Retains the payment provider chosen while a cart moves through checkout.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE cart_payment_sessions (\n  -- A cart has one active provider choice; retrying replaces that choice.\n  cart_id     TEXT PRIMARY KEY REFERENCES carts (id) ON DELETE CASCADE,\n  -- Public provider identifier; no card or provider secret is stored here.\n  provider_id TEXT NOT NULL CHECK (length(trim(provider_id)) > 0),\n  created_at  TEXT NOT NULL DEFAULT\n              (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at  TEXT NOT NULL DEFAULT\n              (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\'))\n);\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER cart_payment_sessions_touch_updated_at\nAFTER UPDATE ON cart_payment_sessions\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE cart_payment_sessions\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE cart_id = NEW.cart_id;\nEND;\n',
  '20260906150002_region_payment_providers.up.sql': '-- Declares which payment providers a selling region can offer at checkout.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE region_payment_providers (\n  -- Provider identifiers are public API values such as "manual".\n  provider_id TEXT NOT NULL CHECK (length(trim(provider_id)) > 0),\n  -- A provider is configured independently for each currency and territory.\n  region_id   TEXT NOT NULL REFERENCES regions (id) ON DELETE CASCADE,\n  -- Disabled rows preserve merchant configuration without advertising it.\n  enabled     INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),\n  created_at  TEXT NOT NULL DEFAULT\n              (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at  TEXT NOT NULL DEFAULT\n              (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  PRIMARY KEY (region_id, provider_id)\n);\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER region_payment_providers_touch_updated_at\nAFTER UPDATE ON region_payment_providers\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE region_payment_providers\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE region_id = NEW.region_id AND provider_id = NEW.provider_id;\nEND;\n',
  '20260906150003_product_image_variants.up.sql': '-- Associates product gallery images with the variants that should display them.\n-- An image without rows remains visible for every variant of its product.\nCREATE TABLE product_image_variants (\n  image_id   TEXT NOT NULL REFERENCES product_images (id) ON DELETE CASCADE,\n  variant_id TEXT NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,\n  -- SQLite generates the immutable UTC audit instant for each association.\n  created_at TEXT NOT NULL DEFAULT\n             (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  PRIMARY KEY (image_id, variant_id)\n);\n\nCREATE INDEX idx_product_image_variants_variant\nON product_image_variants (variant_id, image_id);\n\n-- Both sides must be active children of the same product. Foreign keys alone\n-- cannot express that cross-table ownership invariant in SQLite.\nCREATE TRIGGER product_image_variants_same_product_insert\nBEFORE INSERT ON product_image_variants\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM product_images image\n  JOIN product_variants variant ON variant.product_id = image.product_id\n  WHERE image.id = NEW.image_id\n    AND variant.id = NEW.variant_id\n    AND image.deleted_at IS NULL\n    AND variant.deleted_at IS NULL\n)\nBEGIN\n  SELECT RAISE(ABORT, \'image and variant must belong to the same product\');\nEND;\n\n-- Associations are immutable pairs; callers replace them with delete/insert.\nCREATE TRIGGER product_image_variants_immutable\nBEFORE UPDATE ON product_image_variants\nBEGIN\n  SELECT RAISE(ABORT, \'product image variant links are immutable\');\nEND;\n',
  '20260907120000_product_product_options.up.sql': '-- Links reusable options to products without copying the option definition.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_product_options (\n  id                TEXT PRIMARY KEY,\n  product_id        TEXT NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  product_option_id TEXT NOT NULL\n                    REFERENCES product_options (id) ON DELETE CASCADE,\n  created_at        TEXT NOT NULL DEFAULT\n                    (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at        TEXT NOT NULL DEFAULT\n                    (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion detaches an option without erasing historical identity.\n  deleted_at        TEXT\n);\n\nCREATE UNIQUE INDEX idx_product_product_options_active_pair\nON product_product_options (product_id, product_option_id)\nWHERE deleted_at IS NULL;\nCREATE INDEX idx_product_product_options_option\nON product_product_options (product_option_id, product_id)\nWHERE deleted_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_product_options_touch_updated_at\nAFTER UPDATE ON product_product_options\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_product_options\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260907120001_product_product_option_values.up.sql': '-- Limits a product-option link to the global values offered by that product.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE product_product_option_values (\n  id                        TEXT PRIMARY KEY,\n  product_product_option_id TEXT NOT NULL\n                            REFERENCES product_product_options (id)\n                            ON DELETE CASCADE,\n  product_option_value_id   TEXT NOT NULL\n                            REFERENCES product_option_values (id)\n                            ON DELETE CASCADE,\n  created_at                TEXT NOT NULL DEFAULT\n                            (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at                TEXT NOT NULL DEFAULT\n                            (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  -- Soft deletion removes availability without rewriting old variants.\n  deleted_at                TEXT\n);\n\nCREATE UNIQUE INDEX idx_product_product_option_values_active_pair\nON product_product_option_values\n  (product_product_option_id, product_option_value_id)\nWHERE deleted_at IS NULL;\nCREATE INDEX idx_product_product_option_values_value\nON product_product_option_values (product_option_value_id)\nWHERE deleted_at IS NULL;\n\n-- A product can only expose values owned by its linked option.\nCREATE TRIGGER product_product_option_values_validate_insert\nBEFORE INSERT ON product_product_option_values\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM product_product_options link\n  JOIN product_option_values value\n    ON value.option_id = link.product_option_id\n  WHERE link.id = NEW.product_product_option_id\n    AND value.id = NEW.product_option_value_id\n    AND link.deleted_at IS NULL\n    AND value.deleted_at IS NULL\n) BEGIN\n  SELECT raise(ABORT, \'option value does not belong to product option\');\nEND;\n\nCREATE TRIGGER product_product_option_values_validate_update\nBEFORE UPDATE OF product_product_option_id, product_option_value_id\nON product_product_option_values\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM product_product_options link\n  JOIN product_option_values value\n    ON value.option_id = link.product_option_id\n  WHERE link.id = NEW.product_product_option_id\n    AND value.id = NEW.product_option_value_id\n    AND link.deleted_at IS NULL\n    AND value.deleted_at IS NULL\n) BEGIN\n  SELECT raise(ABORT, \'option value does not belong to product option\');\nEND;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER product_product_option_values_touch_updated_at\nAFTER UPDATE ON product_product_option_values\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE product_product_option_values\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE id = NEW.id;\nEND;\n',
  '20260907180000_email_verifications.up.sql': '-- Stores the current single-use email capability for one authentication identity.\n-- UTC timestamps use ISO-8601 TEXT because SQLite has no native TIMESTAMPTZ.\nCREATE TABLE email_verifications (\n  auth_identity_id TEXT PRIMARY KEY REFERENCES auth_identity (id)\n                   ON UPDATE CASCADE ON DELETE CASCADE,\n  -- Only a SHA-256 fingerprint is retained; a database read cannot verify email.\n  token_hash       TEXT UNIQUE CHECK\n                   (token_hash IS NULL OR length(token_hash) = 64),\n  -- Explicit expiry bounds an emailed capability independently of cleanup.\n  expires_at       TEXT NOT NULL,\n  -- A value proves completion; NULL means sign-in must remain unavailable.\n  verified_at      TEXT,\n  created_at       TEXT NOT NULL DEFAULT\n                   (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  updated_at       TEXT NOT NULL DEFAULT\n                   (strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')),\n  CHECK (verified_at IS NOT NULL OR token_hash IS NOT NULL)\n);\n\nCREATE INDEX idx_email_verifications_expiry\nON email_verifications (expires_at)\nWHERE verified_at IS NULL;\n\n-- SQLite has no automatic ON UPDATE timestamp, so this maintains updated_at.\nCREATE TRIGGER email_verifications_touch_updated_at\nAFTER UPDATE ON email_verifications\nWHEN NEW.updated_at = OLD.updated_at BEGIN\n  UPDATE email_verifications\n  SET updated_at = strftime(\'%Y-%m-%dT%H:%M:%fZ\', \'now\')\n  WHERE auth_identity_id = NEW.auth_identity_id;\nEND;\n',
};
